export type TurnCancelParams = {
  readonly thread: ThreadId;
};

export type TurnCancelResult = Readonly<Record<string, never>>;

export type TurnStartParams = {
  readonly _meta?: Meta;
  /** Runs the turn as a task, with no one attached: answered at once with the task. */
  readonly background?: boolean;
  /** With `background`, tokens the turn may use, subagents' included. */
  readonly budget?: number | null;
  readonly prompt: string;
  readonly thread: ThreadId;
};

export type TurnStartResult = {
  readonly turn: TurnResult;
} | {
  readonly task: TaskInfo;
};

/** Every method, with its params and result. */
export interface Methods {
  readonly "approval/decide": { readonly params: ApprovalDecideParams; readonly result: ApprovalDecideResult };
  readonly "goal/get": { readonly params: GoalGetParams; readonly result: GoalGetResult };
  readonly "goal/start": { readonly params: GoalStartParams; readonly result: GoalStartResult };
  readonly "goal/stop": { readonly params: GoalStopParams; readonly result: GoalStopResult };
  readonly "memory/edit": { readonly params: MemoryEditParams; readonly result: MemoryEditResult };
  readonly "memory/forget": { readonly params: MemoryForgetParams; readonly result: MemoryForgetResult };
  readonly "memory/list": { readonly params: MemoryListParams; readonly result: MemoryListResult };
  readonly "memory/move": { readonly params: MemoryMoveParams; readonly result: MemoryMoveResult };
  readonly "memory/restore": { readonly params: MemoryRestoreParams; readonly result: MemoryRestoreResult };
  readonly "memory/save": { readonly params: MemorySaveParams; readonly result: MemorySaveResult };
  readonly "question/answer": { readonly params: QuestionAnswerParams; readonly result: QuestionAnswerResult };
  readonly "schedule/create": { readonly params: ScheduleCreateParams; readonly result: ScheduleCreateResult };
  readonly "schedule/delete": { readonly params: ScheduleDeleteParams; readonly result: ScheduleDeleteResult };
  readonly "schedule/list": { readonly params: ScheduleListParams; readonly result: ScheduleListResult };
  readonly "server/discover": { readonly params: ServerDiscoverParams; readonly result: ServerDiscoverResult };
  readonly "space/create": { readonly params: SpaceCreateParams; readonly result: SpaceCreateResult };
  readonly "space/get": { readonly params: SpaceGetParams; readonly result: SpaceGetResult };
  readonly "space/list": { readonly params: SpaceListParams; readonly result: SpaceListResult };
  readonly "space/rename": { readonly params: SpaceRenameParams; readonly result: SpaceRenameResult };
  readonly "tasks/list": { readonly params: TasksListParams; readonly result: TasksListResult };
  readonly "tasks/stop": { readonly params: TasksStopParams; readonly result: TasksStopResult };
  readonly "thread/archive": { readonly params: ThreadArchiveParams; readonly result: ThreadArchiveResult };
  readonly "thread/compact": { readonly params: ThreadCompactParams; readonly result: ThreadCompactResult };
  readonly "thread/delete": { readonly params: ThreadDeleteParams; readonly result: ThreadDeleteResult };
  readonly "thread/events": { readonly params: ThreadEventsParams; readonly result: ThreadEventsResult };
  readonly "thread/get": { readonly params: ThreadGetParams; readonly result: ThreadGetResult };
  readonly "thread/list": { readonly params: ThreadListParams; readonly result: ThreadListResult };
  readonly "thread/rename": { readonly params: ThreadRenameParams; readonly result: ThreadRenameResult };
  readonly "thread/start": { readonly params: ThreadStartParams; readonly result: ThreadStartResult };
  readonly "thread/unarchive": { readonly params: ThreadUnarchiveParams; readonly result: ThreadUnarchiveResult };
  readonly "turn/cancel": { readonly params: TurnCancelParams; readonly result: TurnCancelResult };
  readonly "turn/start": { readonly params: TurnStartParams; readonly result: TurnStartResult };
}

export type Method = keyof Methods;

/** The methods that answer with server-sent events, unless run in the background. */
export const STREAMING = ["goal/start", "turn/start"] as const;

export type StreamingMethod = (typeof STREAMING)[number];

export type TaskFinishedParams = {
  readonly task: TaskInfo;
  readonly thread: ThreadId;
};

export type ThreadEventParams = {
  readonly event: RawEvent;
  readonly thread: ThreadId;
};

export type TurnLiveParams = {
  readonly thread: ThreadId;
  readonly update: Update;
};

/** What a server sends while a turn runs or a client watches. */
export type Notification =
  | { readonly jsonrpc: "2.0"; readonly method: "task/finished"; readonly params: TaskFinishedParams }
  | { readonly jsonrpc: "2.0"; readonly method: "thread/event"; readonly params: ThreadEventParams }
  | { readonly jsonrpc: "2.0"; readonly method: "turn/live"; readonly params: TurnLiveParams };

/** The error codes a request may be answered with. */
export const ErrorCode = {
  /** The thread is archived; unarchive it first */
  ARCHIVED: -32014,
  /** The operation was cancelled */
  CANCELLED: -32005,
  /** The server failed */
  INTERNAL: -32603,
  /** The params are not valid */
  INVALID_PARAMS: -32602,
  /** The message is not a valid request */
  INVALID_REQUEST: -32600,
  /** A policy limit was reached */
  LIMIT: -32015,
  /** Memory is off for this server */
  MEMORY_OFF: -32018,
  /** The caller may not do this */
  NOT_ALLOWED: -32012,
  /** No such approval is pending */
  NO_APPROVAL: -32004,
  /** The thread has no active goal (or, to resume, no paused one) */
  NO_GOAL: -32007,
  /** No such memory here */
  NO_MEMORY: -32017,
  /** No such method */
  NO_METHOD: -32601,
  /** No such question is waiting */
  NO_QUESTION: -32006,
  /** No such schedule */
  NO_SCHEDULE: -32016,
  /** No valid sign-in (network transports) */
  NO_SIGN_IN: -32013,
  /** No such space */
  NO_SPACE: -32019,
  /** No such thread */
  NO_THREAD: -32001,
  /** No turn is running in this thread */
  NO_TURN: -32003,
  /** The message is not JSON-RPC */
  PARSE: -32700,
  /** A hook stopped the prompt */
  PROMPT_BLOCKED: -32008,
  /** The model provider failed */
  PROVIDER: -32020,
  /** The thread is running in another server of this deployment */
  RUNNING_ELSEWHERE: -32011,
  /** A turn is already running in this thread */
  TURN_RUNNING: -32002,
  /** Unsupported protocol version */
  UNSUPPORTED_PROTOCOL: -32010,
  /** The thread's workspace could not be opened */
  WORKSPACE: -32009,
} as const;
